"""Stable D-012A1 supervision failures."""
CODES = frozenset({"FREEZE_HASH_MISMATCH","STARTING_COMMIT_MISMATCH","D010_ENABLED","NON_DISPOSABLE_DRY_RUN_DATABASE","DUPLICATE_CAMPAIGN","DATABASE_ALREADY_OWNED","STALE_LOCK_UNSAFE","PID_IDENTITY_MISMATCH","CHECKPOINT_INCOMPLETE","PROGRESS_STATE_CORRUPT","ORGANISM_START_FAILED","ORGANISM_EXIT_UNEXPECTED","SUPERVISOR_RECOVERY_FAILED","EVIDENCE_PATH_INVALID","PREREQUISITE_SEAL_INVALID","REAL_DEVICE_CONFIG_PROHIBITED"})
class SupervisionError(RuntimeError):
    def __init__(self, code: str, reason: str = "") -> None:
        self.code = code if code in CODES else "SUPERVISOR_RECOVERY_FAILED"
        super().__init__(f"{self.code}:{reason}" if reason else self.code)
